{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Normalize input item embeddings by their coordinate RMS with epsilon 1e-6 and a jointly learned scalar initialized to the initial nonpadding embedding RMS. This may reduce GRU gate saturation. Padding remains zero and candidate embeddings remain unchanged. The generated predictor imports this model class and loads the scalar from the same checkpoint, preserving training/inference consistency.",
      "edits": [
        {
          "find": "            self.item_emb.weight[0].zero_()\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "            self.item_emb.weight[0].zero_()\n            self.input_embedding_scale = nn.Parameter(\n                self.item_emb.weight[1:].square().mean().sqrt()\n            )\n\n    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        rms = emb.square().mean(dim=-1, keepdim=True).clamp_min(1e-12).sqrt()\n        emb = self.input_embedding_scale * (emb / rms.clamp_min(1e-6))\n        return emb.masked_fill((seq == 0).unsqueeze(-1), 0.0)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.input_embeddings(seq))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.input_embeddings(seq))"
        }
      ]
    }
  ],
  "change_summary": "Add input-only RMS embedding normalization with a learned scalar shared across items. Preserve GRU topology, candidate scoring, training settings, and one checkpoint per category."
}
